import{MASKS}from'./pins.mjs';
const sha=async b=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',b)),x=>x.toString(16).padStart(2,'0')).join('');
// Compiled transport only. Return fresh original bytes; no cache, geometry/revision changes or borrowed state.
export async function loadS1CompiledMask(key,{fetcher=fetch,signal}={}){if(typeof key!=='string'||!Object.hasOwn(MASKS,key))throw Error('S1_MASK_KEY');const p=MASKS[key],check=()=>{if(signal?.aborted)throw Error('S1_MASK_ABORTED')};check();const response=await fetcher(new URL(p.file,import.meta.url),{signal});check();if(!response.ok)throw Error('S1_MASK_HTTP');const raw=await response.arrayBuffer();check();if(!(raw instanceof ArrayBuffer)&&!ArrayBuffer.isView(raw))throw Error('S1_MASK_BUFFER');if(raw.byteLength!==p.artifactBytes)throw Error('S1_MASK_PACKED_SIZE');const bytes=(raw instanceof ArrayBuffer?new Uint8Array(raw):new Uint8Array(raw.buffer,raw.byteOffset,raw.byteLength)).slice();if(await sha(bytes)!==p.artifactSHA256)throw Error('S1_MASK_PACKED_PIN');check();const v=new DataView(bytes.buffer),header=new TextDecoder().decode(bytes.subarray(0,8));if(header!=='S1MASKR1'||v.getUint32(8,true)!==p.width||v.getUint32(12,true)!==p.height||v.getUint32(16,true)!==p.decodedBytes||v.getUint32(20,true)!==p.runCount||v.getUint32(24,true)!==p.safeCells||v.getUint32(28,true)!==0||bytes.length!==64+p.runCount*8||Array.from(bytes.subarray(32,64),x=>x.toString(16).padStart(2,'0')).join('')!==p.logicalSHA256)throw Error('S1_MASK_HEADER');check();let prior=-1,count=0;for(let i=0;i<p.runCount;i++){const a=v.getUint32(64+i*8,true),b=v.getUint32(68+i*8,true);if(a<=prior||a>=b||b>p.decodedBytes)throw Error('S1_MASK_RUN');prior=b;count+=b-a}if(count!==p.safeCells)throw Error('S1_MASK_COUNT');check();const decoded=new Uint8Array(p.decodedBytes);for(let i=0;i<p.runCount;i++)decoded.fill(1,v.getUint32(64+i*8,true),v.getUint32(68+i*8,true));check();if(await sha(decoded)!==p.logicalSHA256)throw Error('S1_MASK_LOGICAL_PIN');check();return decoded}
